"use strict";
import { useQuery } from "@tanstack/react-query";
import { useMemo } from "react";
import { getAbstractSubgraphs } from "uniswap/src/constants/abstractContracts";
import { UniverseChainId } from "uniswap/src/features/chains/types";
import { toGraphQLChain } from "uniswap/src/features/chains/utils";
const TOKEN_QUERY = `
  query GetToken($tokenAddress: String!) {
    token(id: $tokenAddress) {
      id
      symbol
      name
      decimals
    }
  }
`;
const TOKEN_POOLS_V2_QUERY = `
  query GetTokenPoolsV2($tokenAddress: String!) {
    pairs(
      where: {
        or: [
          { token0: $tokenAddress }
          { token1: $tokenAddress }
        ]
      }
      first: 100
      orderBy: reserveUSD
      orderDirection: desc
    ) {
      id
      token0 {
        id
        symbol
        name
        decimals
      }
      token1 {
        id
        symbol
        name
        decimals
      }
      reserve0
      reserve1
      reserveUSD
      volumeUSD
      stable
    }
  }
`;
const TOKEN_POOLS_V3_QUERY = `
  query GetTokenPoolsV3($tokenAddress: String!) {
    pools(
      where: {
        or: [
          { token0: $tokenAddress }
          { token1: $tokenAddress }
        ]
      }
      first: 100
      orderBy: totalValueLockedUSD
      orderDirection: desc
    ) {
      id
      token0 {
        id
        symbol
        name
        decimals
      }
      token1 {
        id
        symbol
        name
        decimals
      }
      totalValueLockedUSD
      volumeUSD
      tickSpacing
    }
  }
`;
async function fetchFromSubgraph(url, query, variables) {
  try {
    const response = await fetch(url, {
      method: "POST",
      headers: {
        "Content-Type": "application/json"
      },
      body: JSON.stringify({
        query,
        variables
      })
    });
    const data = await response.json();
    if (data.errors) {
      console.error("Subgraph errors:", data.errors);
      return null;
    }
    return data.data;
  } catch (error) {
    console.error("Failed to fetch from subgraph:", error);
    return null;
  }
}
export function useAbstractTokenData(tokenAddress, chainId = UniverseChainId.Mainnet) {
  const query = useQuery({
    queryKey: ["abstract-token", tokenAddress, chainId],
    queryFn: async () => {
      if (!tokenAddress) {
        throw new Error("Token address is required");
      }
      const subgraphs = getAbstractSubgraphs(chainId);
      const lowerTokenAddress = tokenAddress.toLowerCase();
      const [v2TokenData, v3TokenData] = await Promise.all([
        fetchFromSubgraph(subgraphs.v2, TOKEN_QUERY, { tokenAddress: lowerTokenAddress }),
        fetchFromSubgraph(subgraphs.v3, TOKEN_QUERY, { tokenAddress: lowerTokenAddress })
      ]);
      const tokenInfo = v2TokenData?.token || v3TokenData?.token;
      if (!tokenInfo) {
        throw new Error("Token not found in subgraphs");
      }
      const [v2PoolsData, v3PoolsData] = await Promise.all([
        fetchFromSubgraph(subgraphs.v2, TOKEN_POOLS_V2_QUERY, { tokenAddress: lowerTokenAddress }),
        fetchFromSubgraph(subgraphs.v3, TOKEN_POOLS_V3_QUERY, { tokenAddress: lowerTokenAddress })
      ]);
      const v2Pools = v2PoolsData?.pairs || [];
      const v3Pools = v3PoolsData?.pools || [];
      const totalV2TVL = v2Pools.reduce(
        (sum, pool) => sum + parseFloat(pool.reserveUSD || "0"),
        0
      );
      const totalV3TVL = v3Pools.reduce(
        (sum, pool) => sum + parseFloat(pool.totalValueLockedUSD || "0"),
        0
      );
      const totalV2Volume = v2Pools.reduce(
        (sum, pool) => sum + parseFloat(pool.volumeUSD || "0"),
        0
      );
      const totalV3Volume = v3Pools.reduce(
        (sum, pool) => sum + parseFloat(pool.volumeUSD || "0"),
        0
      );
      const result = {
        address: tokenInfo.id,
        name: tokenInfo.name,
        symbol: tokenInfo.symbol,
        decimals: parseInt(tokenInfo.decimals),
        chain: chainId,
        pools: {
          v2: v2Pools,
          v3: v3Pools
        },
        totalValueLocked: totalV2TVL + totalV3TVL,
        totalVolume: totalV2Volume + totalV3Volume,
        poolCount: v2Pools.length + v3Pools.length,
        // Mock project structure to match expected interfaces
        project: {
          id: tokenInfo.id,
          name: tokenInfo.name,
          tokens: [
            {
              id: tokenInfo.id,
              address: tokenInfo.id,
              chain: toGraphQLChain(chainId),
              // Convert to GraphQL chain format
              symbol: tokenInfo.symbol,
              name: tokenInfo.name,
              decimals: parseInt(tokenInfo.decimals)
            }
          ],
          markets: [
            {
              price: {
                value: 0
                // Price discovery would need additional calculation
              }
            }
          ]
        }
      };
      return result;
    },
    enabled: !!tokenAddress,
    refetchInterval: 3e4,
    // Refetch every 30 seconds
    retry: 2
  });
  return {
    loading: query.isLoading,
    error: !!query.error,
    data: query.data
  };
}
export function useAbstractTokenWebQuery(variables) {
  const { data, loading, error } = useAbstractTokenData(variables.address);
  return useMemo(() => ({
    data: data ? {
      token: {
        id: data.address,
        address: data.address,
        chain: toGraphQLChain(data.chain),
        // Convert to GraphQL chain format
        symbol: data.symbol,
        name: data.name,
        decimals: data.decimals,
        project: {
          ...data.project,
          // Provide empty market cap / FDV objects to align with consumers
          markets: [
            {
              ...data.project?.markets?.[0] ?? {},
              marketCap: data.totalValueLocked !== void 0 ? { value: void 0 } : void 0,
              fullyDilutedValuation: data.totalValueLocked !== void 0 ? { value: void 0 } : void 0
            }
          ]
        },
        // Add market data structure expected by StatsSection
        market: {
          price: {
            value: data.project?.markets?.[0]?.price?.value || 0
          },
          totalValueLocked: data.totalValueLocked !== void 0 ? { value: data.totalValueLocked } : void 0,
          volume24H: void 0
        }
      }
    } : void 0,
    loading,
    error: error ? new Error("Failed to fetch token data") : void 0
  }), [data, loading, error]);
}
